use v5.40;
use DBI;
use Time::HiRes qw(time sleep);
use JSON::MaybeXS qw(decode_json encode_json);
use Mojo::File qw(path);
my ($run)=@ARGV;
my $info=decode_json(path("$run/result/observer-dsn.json")->slurp);
my $db=DBI->connect($info->{dsn},'postgres','',{RaiseError=>1,AutoCommit=>1});
my @history;
while (!-e "$run/result/observer-stop") {
 my $rows=$db->selectall_arrayref(q{SELECT state, wait_event_type, wait_event, count(*)::integer AS connections FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() GROUP BY 1,2,3},{Slice=>{}});
 push @history,{time=>time,states=>$rows};
 sleep .05;
}
path("$run/waits.json")->spurt(encode_json(\@history));
$db->disconnect;

run-features.pl.source:
use v5.40;
use Test::PostgreSQL;
use DBI;
use GPForum::Command::Migrate;
use GPForum::Command::PerformanceSeed;
use GPForum::Command::QueryBudget;
my ($run)=@ARGV;
my $pg=Test::PostgreSQL->new(unix_socket=>1,extra_initdb_args=>'--encoding=UTF8 --no-locale',extra_postmaster_args=>'-c max_connections=100') or die 'temporary PostgreSQL unavailable';
my $dbh=DBI->connect($pg->dsn(dbname=>'postgres'),'postgres','',{RaiseError=>1,AutoCommit=>1});
$dbh->do('CREATE DATABASE gpforum_test');$dbh->disconnect;
$ENV{GPFORUM_ENV}='test';
$ENV{GPFORUM_DATABASE_DSN}=$pg->dsn(dbname=>'gpforum_test');
$ENV{GPFORUM_TEST_DSN}=$ENV{GPFORUM_DATABASE_DSN};
$ENV{GPFORUM_DATABASE_USER}='postgres';$ENV{GPFORUM_DATABASE_PASSWORD}='';
$ENV{GPFORUM_POSTGRES_CONTROLLED_TEST}=1;
GPForum::Command::Migrate->new->run('--apply')==0 or die 'migration failed';
GPForum::Command::PerformanceSeed->new->run('--profile','small')==0 or die 'seed failed';
GPForum::Command::QueryBudget->new->run('--sync')==0 or die 'budgets failed';
my $status=system('script/gpforum-carton','exec','script/test-features','--configured','--jobs','2','--output',"$run/features");
$pg->stop;
exit($status ? 1 : 0);

